stageRows.noteAfterStage:
{
  "rules": [
    {
      "id": "P1-L1",
      "quote": "Implement a reconciliation tool for an e-commerce settlement team."
    },
    {
      "id": "P1-L2",
      "quote": "These rules apply throughout the tool: - Store every amount as integer cents and process only `USD` records."
    },
    {
      "id": "P1-L3",
      "quote": "- Silently skip invalid records;"
    },
    {
      "id": "P1-L5",
      "quote": "- An amount whose absolute value exceeds `1,000,000` cents (`$10,000.00`) is invalid."
    },
    {
      "id": "P1-L10",
      "quote": "Each line has six `|`-separated fields: ```text TYPE|RECORD_ID|ORDER_ID|AMOUNT|CURRENCY|TIMESTAMP ``` `TYPE` is case-insensitive `ORDER` or `PAYMENT` and is stored uppercase."
    },
    {
      "id": "P1-L12",
      "quote": "Amounts contain digits and at most one decimal point, with an optional leading minus sign."
    },
    {
      "id": "P1-L15",
      "quote": "round a third digit to cents using round-half-up."
    },
    {
      "id": "P1-L35",
      "quote": "`parse_record(line)` applies the six-field format, ID, currency, timestamp, and negative-order rules and returns a dictionary with exactly `type`, `record_id`, `order_id`, `amount`, `currency`, and `timestamp`, or `None`."
    }
  ],
  "checks": [
    {
      "assertion": "assert parse_amount('10.50') == 1050",
      "result": "OBSERVED_PASS",
      "ttl": 2
    },
    {
      "assertion": "assert parse_amount('-10.50') == -1050",
      "result": "OBSERVED_PASS",
      "ttl": 2
    },
    {
      "assertion": "assert parse_amount('1000000.01') is None",
      "result": "OBSERVED_PASS",
      "ttl": 2
    }
  ],
  "status": {},
  "todo": []
}

