{
  "rules": [
    {
      "id": "P1-L1",
      "quote": "Implement a reconciliation tool for an e-commerce settlement team."
    },
    {
      "id": "P1-L2",
      "quote": "These rules apply throughout the tool: - Store every amount as integer cents and process only `USD` records."
    },
    {
      "id": "P1-L3",
      "quote": "- Silently skip invalid records;"
    },
    {
      "id": "P1-L5",
      "quote": "- An amount whose absolute value exceeds `1,000,000` cents (`$10,000.00`) is invalid."
    },
    {
      "id": "P4-L10",
      "quote": "Each line has six `|`-separated fields: ```text TYPE|RECORD_ID|ORDER_ID|AMOUNT|CURRENCY|TIMESTAMP ``` `TYPE` is case-insensitive `ORDER` or `PAYMENT` and is stored uppercase."
    },
    {
      "id": "P4-L11",
      "quote": "IDs must remain non-empty after trimming."
    },
    {
      "id": "P4-L12",
      "quote": "Amounts contain digits and at most one decimal point, with an optional leading minus sign."
    },
    {
      "id": "P4-L13",
      "quote": "Scientific notation is invalid."
    },
    {
      "id": "P4-L16",
      "quote": "Negative orders are invalid and negative payments are refunds."
    },
    {
      "id": "P4-L17",
      "quote": "Duplicate record IDs keep the first valid occurrence."
    },
    {
      "id": "P4-L18",
      "quote": "Only refunds whose `order_id` belongs to an existing order count toward the refund total."
    },
    {
      "id": "P4-L19",
      "quote": "Final unmatched order IDs must be unique."
    }
  ],
  "checks": [
    {
      "assertion": "assert parse_record('ORDER|ID1|ORD-123|100.00|USD|2023-10-01 12:00') == {'type': 'ORDER', 'record_id': 'ID1', 'order_id': 'ORD-123', 'amount': 10000, 'currency': 'USD', 'timestamp': '2023-10-01 12:00'}",
      "result": "OBSERVED_FAIL",
      "ttl": 1
    },
    {
      "assertion": "assert parse_record('PAYMENT|ID2|ORD-123|-50.00|USD|2023-10-01 12:00') == {'type': 'PAYMENT', 'record_id': 'ID2', 'order_id': 'ORD-123', 'amount': -5000, 'currency': 'USD', 'timestamp': '2023-10-01 12:00'}",
      "result": "OBSERVED_FAIL",
      "ttl": 1
    },
    {
      "assertion": "assert load_records('ORDER|ID1|ORD-123|100.00|USD|2023-10-01 12:00\\nPAYMENT|ID2|ORD-123|-50.00|USD|2023-10-01 12:00') == [{'type': 'ORDER', 'record_id': 'ID1', 'order_id': 'ORD-123', 'amount': 10000, 'currency': 'USD', 'timestamp': '2023-10-01 12:00'}, {'type': 'PAYMENT', 'record_id': 'ID2', 'order_id': 'ORD-123', 'amount': -5000, 'currency': 'USD', 'timestamp': '2023-10-01 12:00'}]",
      "result": "OBSERVED_FAIL",
      "ttl": 1
    }
  ],
  "status": {},
  "todo": []
}

